/** Group the signals per (dashboard, source) for ensureSeed(). */
export function hiEnergySeedGroups(): HiEnergySeedGroup[] {
  const map = new Map<string, HiEnergySeedGroup>();
  for (const { campaigns, source, ...signal } of HI_ENERGY_SIGNALS) {
    for (const campaignId of campaigns) {
      const key = `${campaignId}|${source}`;
      let g = map.get(key);
      if (!g) {
        g = { campaignId, source, signals: [] };
        map.set(key, g);
      }
      g.signals.push(signal);
    }
  }
  return [...map.values()];
}

